<script>
  import {language} from '$lib/config';export let data;export let i18n=null;let country='';
  $: providers=data?.providers||{languages:[],providers:[]};$: regions=providers.languages.map(code=>({code,name:new Intl.DisplayNames([$language||'et'],{type:'region'}).of(code)||code}));$: selected=regions.find(x=>x.name===country)?.code||country;$: list=providers.providers.filter(x=>!selected||x.lang.includes(selected));
  const url=(name)=>`https://www.google.com/search?q=${encodeURIComponent(`${name} ${data?.title||''}`)}`;
</script>
<section class="provider-panel"><header><div><span class="eyebrow">Kus vaadata?</span><h3>Voogedastuspakkujad</h3></div><label>Piirkond<input bind:value={country} list="provider-regions" placeholder="Kõik piirkonnad"><datalist id="provider-regions">{#each regions as region}<option value={region.name}></option>{/each}</datalist></label></header>{#if list.length}<div class="provider-grid">{#each list as provider}<a href={url(provider.name)} target="_blank" rel="noreferrer"><span>{provider.name.slice(0,1)}</span><b>{provider.name}</b><i>↗</i></a>{/each}</div>{:else}<p class="provider-empty">Selles piirkonnas pakkujaid ei leitud.</p>{/if}</section>
<style>.provider-panel{min-width:0}.provider-panel header{display:flex;align-items:end;justify-content:space-between;gap:16px;margin-bottom:18px}.provider-panel h3{margin:0;font-size:22px}.provider-panel label{display:grid;gap:5px;color:var(--muted);font-size:10px}.provider-panel input{background:#0d0d11;color:white;border:1px solid var(--line);border-radius:9px;padding:10px}.provider-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(210px,100%),1fr));gap:9px}.provider-grid a{display:grid;grid-template-columns:38px minmax(0,1fr) auto;align-items:center;gap:10px;padding:11px;background:#1b1b21;border:1px solid var(--line);border-radius:12px;color:white;text-decoration:none}.provider-grid a:hover{border-color:#735721;transform:translateY(-1px)}.provider-grid a>span{width:38px;height:38px;display:grid;place-items:center;border-radius:10px;background:var(--gold);color:#181005;font-weight:900}.provider-grid b{min-width:0}.provider-grid i{color:var(--gold);font-style:normal}.provider-empty{color:var(--muted)}@media(max-width:600px){.provider-panel header{display:grid}.provider-grid{grid-template-columns:1fr}}</style>
